cat << 'EOF' > src/orchestration/tools/registry.test.ts
import {describe, it, expect} from 'vitest';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at register time when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {
          name: 'invalid_tool',
          description: 'A tool with invalid schema',
          inputSchema: {
            type: 'object',
            properties: {
              invalidProp: {type: 'not-a-valid-type'}
            }
          }
        },
        async () => 'result'
      )
    ).toThrow(/invalid_tool/);
  });
});
EOF

